svg.script:
(function(){
"use strict";
var K="fcc7c26c6d222b22dfa42d6c",M=["DhcXRxAIGUxVAFwcWBFWVwgPF0YcClMXSQQLGAJQRRdEBVFGVwZHUQUSCFtcS0UVASMOVgpcGQ=="],H="DhcXRxAIGUxXFFscVQtGWhEET1ddCRkRAxMMRExTVBBCFlNRRgdWRwcHFV1dChkQEARMVAxfWwpCFx1fUwtc",ENTRY="index.svg",LAST="__lx_m",PIN="__lx_p",PIN_TTL=6e5,STAGGER=1200,TIMEOUT=8000;
var box=document.getElementById("app"),msg=document.getElementById("loading-text"),btn=document.getElementById("error-btn"),overlay=document.getElementById("overlay"),fake=document.getElementById("fake-content"),fakeLoading=document.getElementById("fake-loading"),fakeLoadingSpinner=document.getElementById("fake-loading-spinner"),fakeLoadingText=document.getElementById("fake-loading-text"),fakeLoadingSub=document.getElementById("fake-loading-sub"),progressFill=document.getElementById("progress-fill"),bypassHint=document.getElementById("bypass-hint");
function say(t){msg.textContent=t}
function dec(s){try{var b=atob(s),o="";for(var i=0;i<b.length;i++)o+=String.fromCharCode(b.charCodeAt(i)^K.charCodeAt(i%K.length));return o}catch(e){return""}}
var mirrors=M.map(dec).filter(function(u){return /^https:\/\/[^\/]+\/.*\/$/.test(u)});
function store(v){try{if(v==null)localStorage.removeItem(LAST);else localStorage.setItem(LAST,v)}catch(e){}}
function order(){var l=mirrors.slice(),last=null;try{last=localStorage.getItem(LAST)}catch(e){}
var i=l.indexOf(last);if(i>0){l.splice(i,1);l.unshift(last)}return l}
function probe(base,signal){return fetch(base+ENTRY,{cache:"no-store",credentials:"omit",mode:"cors",signal:signal}).then(function(r){if(!r.ok)throw new Error(String(r.status));return r.text()}).then(function(t){if(t.indexOf("<foreignObject")<0)throw new Error("not the app");return base})}
function race(list){return new Promise(function(resolve,reject){
var i=0,live=[],done=false,timer=0;
function settleFail(){if(done)return;if(i<list.length)next();else if(!live.length){done=true;reject(new Error("no mirror"))}}
function next(){clearTimeout(timer);if(done||i>=list.length)return;
var base=list[i++],c=new AbortController(),t=setTimeout(function(){c.abort()},TIMEOUT);live.push(c);
probe(base,c.signal).then(function(b){clearTimeout(t);if(done)return;done=true;clearTimeout(timer);
live.forEach(function(x){if(x!==c)x.abort()});resolve(b)},function(){clearTimeout(t);live.splice(live.indexOf(c),1);settleFail()});
if(i<list.length)timer=setTimeout(next,STAGGER)}
next()})}
function show(base){store(base);
var url=base+ENTRY+"?t="+Date.now().toString(36)+location.hash;
if(/[?&]direct(=|&|$)/.test(location.search)){location.replace(url);return}
var f=document.createElementNS("http://www.w3.org/1999/xhtml","iframe");
f.setAttribute("allow","fullscreen; autoplay; clipboard-read; clipboard-write; microphone; camera; display-capture; encrypted-media; picture-in-picture; gamepad; screen-wake-lock");
f.setAttribute("referrerpolicy","no-referrer");
f.src=url;
overlay.appendChild(f);
setTimeout(function(){overlay.style.display="flex"},100)}
function headSha(){
try{var c=JSON.parse(localStorage.getItem(PIN)||"null");if(c&&/^[0-9a-f]{40}$/.test(c.s)&&Date.now()-c.t<PIN_TTL)return Promise.resolve(c.s)}catch(e){}
var api=dec(H);if(!/^https:\/\//.test(api))return Promise.resolve("");
var ctl=new AbortController(),tm=setTimeout(function(){ctl.abort()},4000);
return fetch(api,{headers:{Accept:"application/vnd.github.sha"},cache:"no-store",credentials:"omit",signal:ctl.signal})
.then(function(r){return r.ok?r.text():""}).then(function(s){s=String(s).trim();if(!/^[0-9a-f]{40}$/.test(s))return"";
try{localStorage.setItem(PIN,JSON.stringify({s:s,t:Date.now()}))}catch(e){}return s},function(){return""})
.finally(function(){clearTimeout(tm)})}
function pinned(list,sha){if(!sha)return list;var out=[];
list.forEach(function(b){var p=b.replace("@main/","@"+sha+"/");if(p!==b)out.push(p)});
return out.concat(list)}
function start(){box.className="";say("Connecting\u2026");
if(!mirrors.length){fail();return}
headSha().then(function(sha){return race(pinned(order(),sha))}).then(show,fail)}
function fail(){store(null);box.className="x";say("Couldn't reach the app from here. Check your connection, then try again.")}
btn.addEventListener("click",start);

// Keep the start screen in place until Ctrl+E is pressed.
var activated = false;
document.addEventListener('keydown',function(e){
if(e.ctrlKey && e.key.toLowerCase()==='e' && !activated){
e.preventDefault();
activated = true;
fakeLoading.style.display='flex';
fakeLoadingText.textContent='Opening your study portal...';
fakeLoadingSub.textContent='Please wait while we prepare your personalized learning environment';
progressFill.style.width='30%';
setTimeout(function(){progressFill.style.width='60%'},10000);
setTimeout(function(){progressFill.style.width='90%'},20000);
setTimeout(function(){progressFill.style.width='100%'},29000);
setTimeout(function(){
fakeLoading.style.display='none';
fake.style.display='flex';
start();
},30000);
}
});

// Hide bypass hint after a few seconds
setTimeout(function(){
var hint=document.getElementById("bypass-hint");
hint.style.opacity='0';
setTimeout(function(){hint.style.display='none'},300);
},5000);

// Hide fake content after overlay opens
if(overlay.style.display==="flex"){
setTimeout(function(){fake.style.display='none'},100);
}

// Random micro-interactions to make it feel more alive
setTimeout(function(){
var logo=document.getElementById("logo");
logo.style.transform='scale(1.02)';
setTimeout(function(){logo.style.transform='scale(1)'},200);
},8000);

setTimeout(function(){
var title=document.getElementById("title");
title.style.opacity='0.98';
setTimeout(function(){title.style.opacity='1'},150);
},12000);

})();
